--===========================================================================
function TriggerRegisterAnyUnitEventBJ(trig, whichEvent)
	local index

	index = 0
	for _ in _loop_() do
		TriggerRegisterPlayerUnitEvent(trig, Player(index), whichEvent, nil)

		index = index + 1
		if index == bj_MAX_PLAYER_SLOTS then break end
	end
end

