		CreateUnit(whichPlayer, 1752196449, peonX + 1.0 * unitSpacing, peonY + 0.0 * unitSpacing, bj_UNIT_FACING)
		CreateUnit(whichPlayer, 1752196449, peonX + 0.0 * unitSpacing, peonY + 0.0 * unitSpacing, bj_UNIT_FACING)
		CreateUnit(whichPlayer, 1752196449, peonX - 1.0 * unitSpacing, peonY + 0.0 * unitSpacing, bj_UNIT_FACING)
