		show = udg_ZhandouZhong and HopeRoute_Active(i - 1) and Player(i - 1) ~= GetLocalPlayer() and u ~= nil and IsUnitAliveBJ(u) and IsUnitVisible(u, GetLocalPlayer()) and HopeMini_Actor[i] == nil
