	f = HopeQoL_Button("HopeRouteInfo", HopeRoute_Panel, 0.089, -0.025, 0.038, 0.022, "说明")
	HopeQoL_Bind(f, HopeRoute_ToggleDetails, false)
	DzFrameShow(HopeRoute_Panel, false)
